class ManagedResource {
    int* ptr;
public:
    // Resource Acquisition (Constructor)
    ManagedResource(size_t size) : ptr(new int[size]) {}

    // Resource Release (Destructor - guaranteed to run)
    ~ManagedResource() { delete[] ptr; }
};

// --- Standard Library RAII ---

struct Item {};

void use_item() {
    // std::unique_ptr handles acquisition/release automatically
    std::unique_ptr<Item> p = std::make_unique<Item>();

    // If a function throws, 'p' is safely destroyed
    risky_operation();
} // Item safely deleted

// --- Synchronization RAII ---

std::mutex mtx;

void safe_access() {
    // std::lock_guard acquires lock immediately
    std::lock_guard<std::mutex> lock(mtx);

    // If an exception occurs here
    critical_computation();

} // Lock automatically released on scope exit
